vec3 palette(float t, vec3 a, vec3 b, vec3 c, vec3 d) {
    return a + b * cos(6.28318 * (c * t + d));
}

float sdEllipse(vec2 p, vec2 r) {
    return (length(p / r) - 1.0) * min(r.x, r.y);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;
    vec2 p = uv;
    p.y += 0.12;

    float pulse = 0.5 + 0.5 * sin(iTime * 1.5);
    float bellH = mix(0.26, 0.36, pulse);
    vec2 r = vec2(0.30, bellH);
    float d = sdEllipse(p, r);

    vec3 deep = mix(vec3(0.0, 0.01, 0.03), vec3(0.0, 0.05, 0.11), clamp(uv.y * 0.5 + 0.5, 0.0, 1.0));
    vec3 col = deep;

    vec3 bellCol = palette(pulse * 0.4 + 0.15, vec3(0.0, 0.3, 0.4), vec3(0.0, 0.4, 0.5), vec3(1.0, 1.0, 1.0), vec3(0.3, 0.5, 0.7));

    float bellGlow = exp(-abs(d) * 16.0);
    col += bellCol * bellGlow * 1.2;

    float inside = smoothstep(0.02, -0.05, d);
    col += bellCol * inside * 0.18;

    for (int i = 0; i < 8; i++) {
        float fi = float(i);
        float tx = (fi / 7.0 - 0.5) * 0.5;
        float wob = sin(iTime * 2.0 + fi * 1.7) * 0.05;
        float ty = clamp((-p.y + bellH * 0.6) / 0.55, 0.0, 1.0);
        float wave = sin(ty * 6.0 + iTime * 3.0 + fi) * 0.05 * ty;
        float tdist = abs(p.x - tx - wave - wob * ty);
        float mask = step(-bellH * 0.6, -p.y) * (1.0 - ty);
        float glow = exp(-tdist * 70.0) * mask;
        col += bellCol * glow * 0.6;
    }

    fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

float hash21(vec2 p) {
    p = fract(p * vec2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return fract(p.x * p.y);
}

float noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    float a = hash21(i);
    float b = hash21(i + vec2(1.0, 0.0));
    float c = hash21(i + vec2(0.0, 1.0));
    float d = hash21(i + vec2(1.0, 1.0));
    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

float fbm(vec2 p) {
    float v = 0.0;
    float a = 0.5;
    for (int i = 0; i < 5; i++) {
        v += a * noise(p);
        p *= 2.0;
        a *= 0.5;
    }
    return v;
}

vec3 palette(float t, vec3 a, vec3 b, vec3 c, vec3 d) {
    return a + b * cos(6.28318 * (c * t + d));
}

vec2 warp(vec2 p, float t) {
    vec2 q = vec2(fbm(p + vec2(0.0, 0.0)), fbm(p + vec2(5.2, 1.3)));
    vec2 r = vec2(fbm(p + 4.0 * q + vec2(1.7, 9.2) + 0.15 * t), fbm(p + 4.0 * q + vec2(8.3, 2.8) + 0.126 * t));
    return r;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;
    vec2 p = uv * 2.0;
    vec2 r = warp(p, iTime * 0.3);
    float f = fbm(p + r * 2.0);

    vec3 deep = mix(vec3(0.0, 0.01, 0.03), vec3(0.0, 0.06, 0.11), clamp(uv.y * 0.5 + 0.5, 0.0, 1.0));
    vec3 col = deep;

    float pulse = 0.5 + 0.5 * sin(iTime * 1.8 + f * 3.0);
    vec3 glowCol = palette(f + iTime * 0.05, vec3(0.1, 0.3, 0.4), vec3(0.2, 0.4, 0.5), vec3(1.0, 0.8, 1.0), vec3(0.0, 0.3, 0.6));

    col += glowCol * f * pulse * 0.9;
    col += glowCol * smoothstep(0.6, 1.0, f) * 0.4;

    fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

float hash21(vec2 p) {
    p = fract(p * vec2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return fract(p.x * p.y);
}

float noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    float a = hash21(i);
    float b = hash21(i + vec2(1.0, 0.0));
    float c = hash21(i + vec2(0.0, 1.0));
    float d = hash21(i + vec2(1.0, 1.0));
    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

vec3 palette(float t, vec3 a, vec3 b, vec3 c, vec3 d) {
    return a + b * cos(6.28318 * (c * t + d));
}

float particles(vec2 p, float t) {
    float v = 0.0;
    for (int i = 0; i < 4; i++) {
        float fi = float(i);
        vec2 q = p * (1.0 + fi * 0.7) + vec2(0.0, t * (0.08 + fi * 0.04));
        float n = noise(q * 8.0);
        v += smoothstep(0.86, 1.0, n) / (fi + 1.0);
    }
    return v;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;
    vec3 col = mix(vec3(0.0, 0.015, 0.05), vec3(0.0, 0.05, 0.1), clamp(uv.y * 0.5 + 0.5, 0.0, 1.0));

    float p = particles(uv, iTime);
    vec3 pcol = palette(p + iTime * 0.1, vec3(0.0, 0.3, 0.4), vec3(0.3, 0.4, 0.5), vec3(1.0, 1.0, 0.8), vec3(0.2, 0.5, 0.7));
    col += pcol * p * 1.5;

    float bell = length(uv - vec2(0.0, 0.1));
    float pulse = 0.4 + 0.15 * sin(iTime * 2.0);
    float glow = exp(-pow(bell / pulse, 2.0) * 6.0);
    col += vec3(0.2, 0.8, 0.9) * glow * 0.5;

    fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

vec3 palette(float t, vec3 a, vec3 b, vec3 c, vec3 d) {
    return a + b * cos(6.28318 * (c * t + d));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;
    float r = length(uv);
    float a = atan(uv.y, uv.x);

    float pulse = 0.5 + 0.5 * sin(iTime * 1.6);
    float petals = 0.5 + 0.5 * cos(a * 8.0 + sin(iTime * 0.7) * 2.0);
    float bellR = 0.32 + 0.08 * pulse + 0.03 * petals;

    float d = abs(r - bellR);
    float ring = exp(-d * 20.0);

    float wave = fract(r * 3.0 - iTime * 0.8);
    float wglow = smoothstep(1.0, 0.0, wave) * smoothstep(0.0, 0.3, r);

    vec3 deep = mix(vec3(0.0, 0.01, 0.04), vec3(0.0, 0.04, 0.09), clamp(r, 0.0, 1.0));
    vec3 col = deep;
    vec3 glowCol = palette(a / 6.28318 + iTime * 0.05, vec3(0.1, 0.3, 0.4), vec3(0.2, 0.3, 0.4), vec3(1.0, 1.0, 1.0), vec3(0.3, 0.6, 0.8));

    col += glowCol * ring * 1.3;
    col += glowCol * wglow * 0.4 * (1.0 - clamp(r, 0.0, 1.0));
    col += glowCol * exp(-r * 4.0) * 0.3;

    fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

vec3 palette(float t, vec3 a, vec3 b, vec3 c, vec3 d) {
    return a + b * cos(6.28318 * (c * t + d));
}

float sdEllipsoid(vec3 p, vec3 r) {
    float k0 = length(p / r);
    float k1 = length(p / (r * r)) + 1e-4;
    return k0 * (k0 - 1.0) / k1;
}

float map(vec3 p, float t) {
    float pulse = 0.5 + 0.5 * sin(t * 1.8);
    vec3 r = vec3(0.9, mix(0.55, 0.75, pulse), 0.9);
    return sdEllipsoid(p, r);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;
    vec3 ro = vec3(0.0, 0.3, -3.0);
    vec3 rd = normalize(vec3(uv, 1.3));

    vec3 col = mix(vec3(0.0, 0.01, 0.03), vec3(0.0, 0.03, 0.08), clamp(uv.y * 0.5 + 0.5, 0.0, 1.0));

    float t = 0.0;
    float glow = 0.0;
    for (int i = 0; i < 48; i++) {
        vec3 p = ro + rd * t;
        float d = map(p, iTime);
        float density = exp(-abs(d) * 6.0) * 0.06;
        glow += density;
        t += max(d * 0.5, 0.03);
        if (t > 8.0) break;
    }

    vec3 glowCol = palette(glow * 2.0 + iTime * 0.1, vec3(0.0, 0.3, 0.4), vec3(0.2, 0.4, 0.5), vec3(1.0, 0.9, 1.0), vec3(0.3, 0.5, 0.7));
    col += glowCol * glow;

    fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

vec3 palette(float t, vec3 a, vec3 b, vec3 c, vec3 d) {
    return a + b * cos(6.28318 * (c * t + d));
}

float bellShape(vec2 p, float t) {
    float pulse = 0.5 + 0.5 * sin(t * 2.0);
    float r = mix(0.25, 0.38, pulse);
    vec2 q = p;
    q.y *= 1.2;
    return length(q) - r;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;
    vec3 col = mix(vec3(0.0, 0.015, 0.04), vec3(0.0, 0.05, 0.1), clamp(uv.y * 0.5 + 0.5, 0.0, 1.0));

    vec2 pos = vec2(0.0, 0.05);

    for (int i = 0; i < 12; i++) {
        float fi = float(i);
        float dt = fi * 0.06;
        float tt = iTime - dt;
        float decay = exp(-fi * 0.35);
        vec2 p = uv - pos - vec2(sin(tt * 0.6) * 0.15, 0.0);
        float d = bellShape(p, tt);
        float glow = exp(-abs(d) * 22.0) * decay;
        vec3 c = palette(tt * 0.15, vec3(0.0, 0.3, 0.45), vec3(0.2, 0.4, 0.5), vec3(1.0, 1.0, 1.0), vec3(0.3, 0.55, 0.75));
        col += c * glow * 0.5;
    }

    fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}
